Here are the common ways to parse `--port` and `--verbose` flags in Node.js:

## Using `process.argv` (built-in)

```javascript
const args = process.argv.slice(2);
let port = 3000;
let verbose = false;

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--port' && args[i + 1]) {
    port = parseInt(args[i + 1], 10);
    i++;
  } else if (args[i] === '--verbose') {
    verbose = true;
  }
}

console.log(`Port: ${port}, Verbose: ${verbose}`);
```

**Usage:**
```bash
node script.js --port 8080 --verbose
```

## Using `minimist` (popular library)

```javascript
const minimist = require('minimist');

const argv = minimist(process.argv.slice(2), {
  default: { port: 3000, verbose: false }
});

console.log(`Port: ${argv.port}, Verbose: ${argv.verbose}`);
```

**Usage:**
```bash
npm install minimist
node script.js --port 8080 --verbose
```

## Using native `parseArgs()` (Node 16.17+)

```javascript
const { parseArgs } = require('util');

const { values, positionals } = parseArgs({
  options: {
    port: { type: 'string', default: '3000' },
    verbose: { type: 'boolean', default: false }
  },
  allowPositionals: true
});

console.log(`Port: ${values.port}, Verbose: ${values.verbose}`);
```

**Usage:**
```bash
node script.js --port 8080 --verbose
```

The **built-in approach** works without dependencies. The **`minimist`** library handles complex cases. The **`parseArgs()`** is modern and built-in if you're on Node 16.17+.

